def label(n):
    if n < 0:
        return "negative"
    elif n == 0:
        return "zero"
    return "positive"

print(label(-1))
print(label(0))
print(label(8))

def count_even(values):
    count = 0
    for value in values:
        if value % 2 == 0:
            count += 1
    return count

print(count_even([1, 2, 3, 4, 6]))
print(count_even([1, 3, 5]))
